promql:
sum by (api) (
  increase(
    (
      api_http_requests_total{job="my-api-monitor", method="PUT", uri="/api/v1/admintravelservice/admintravel"} 
      * on (api) group_left(api) api_http_requests_total{job="my-api-monitor"}
    )[30m]
  )
)

sum by (node_label)(
  container_memory_usage_bytes{container="ts-admin-order-service"} * on (pod) group_left(service) (service:ts-admin-order-service) * on (pod) group_right(node_label) (container_memory_max_usage_bytes)
)

(
  sum by (mode) (rate(container_cpu_usage_seconds_total{node="k8s-node1"}[1m]))
) / ignoring (node) group_left sum by (node) (
  sum by (mode) (rate(container_cpu_usage_seconds_total{node="k8s-node1"}[1m]))
) * 100
+
(
  sum by (mode) (rate(container_cpu_usage_seconds_total{node="k8s-node2"}[1m]))
) / ignoring (node) group_left sum by (node) (
  sum by (mode) (rate(container_cpu_usage_seconds_total{node="k8s-node2"}[1m]))
) * 100

sum by (node)(
  count without(cpu)(node_cpu_socket_count) * on (instance) group_left(node) label_replace(node_cpu_socket_count{node=~"k8s-node[3-5]"}, "node", "$1", "node", "(.*)")
)

sum by (api) (
  increase(
    (
      api_calls_total{source_api="POST /api/v1/routeplanservice/routePlan/quickestRoute"}
      * ignoring(source_api) group_left
      (
        api_calls_total{source_api=~"POST /api/v1/travel2service/trips/left|POST /api/v1/travelservice/trips/left|POST /api/v1/basicservice/basic/travels|POST /api/v1/seatservice/seats/left_tickets"}
      )
    )[1h]
  )
)

(
  histogram_quantile(0.5, sum(rate(http_request_duration_seconds_bucket{job="my-job", service="ts-verification-code-service", span="GET /api/v1/verifycode/verify/{verifyCode}", le="+Inf"}[30m])) by (le))
)
- (
  histogram_quantile(0.5, sum(rate(http_request_duration_seconds_bucket{job="my-job", service="ts-verification-code-service", span="GET /api/v1/verifycode/verify/{verifyCode}", le="+Inf"} offset 24h)[30m])) by (le)
)

(
  rate(receiving_byte_rate[5m]) > 2 * rate(sending_byte_rate[5m])
) 
and 
(
  (
    sum(file_system_read_rate[5m]) + sum(file_system_write_rate[5m])
  ) > 200
) 
unless 
(
  total_io_operation_time < 1e-8
)

sum by (instance)(
  node_network_tcp_connections{state="tw"}
  * on(instance) group_left(service) (
    node_network_tcp_connections{state="tw"}
    * on(instance) group_right(service) (
      service{service="ts-travel-service"}
      * on(pod) group_left(node) (
        pod{namespace="default"} == "ts-travel-service-c598b7879-6mllj"
        or
        pod{namespace="default"} == "ts-travel-service-c598b7879-bb7s2"
      )
      * on(node) group_right(instance) (
        node{node=~"k8s-node1|k8s-node4"}
      )
    )
  )
)

sum by (mode)(
  rate(node_cpu_seconds_total{mode=~"user|system|idle", instance=~"10.176.122.15[1-3]:.*"}[1m])
) / ignoring (cpu) group_left
sum by (cpu)(
  count without(cpu)(node_cpu_seconds_total{instance=~"10.176.122.15[1-3]:.*"}) > 16
) * 100

sum by (direction)(
  irate(network_packet_drops_total{job="node-exporter", instance="10.176.122.161:9100", direction=~"in|out"}[30m])
) / ignoring (direction) group_left
(
  sum by (direction)(
    irate(network_packets_total{job="node-exporter", instance="10.176.122.161:9100", direction=~"in|out"}[30m])
  )
) > 0.05

(
  1 - 
  (
    sum by (service) (
      increase(requests_total{service="ts-gateway-service", status="failure"}[5m])
    ) 
    /
    sum by (service) (
      increase(requests_total{service="ts-gateway-service"}[5m])
    )
  )
)
- 
(
  1 - 
  (
    sum by (service) (
      increase(requests_total{service="ts-gateway-service", status="failure"}[5m] offset 1d)
    ) 
    /
    sum by (service) (
      increase(requests_total{service="ts-gateway-service"}[5m] offset 1d)
    )
  )
)
